@Tags(['golden'])
library;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import '../../support/golden_matrix.dart';

// Goldens for S-40 are generated by CI (`--update-goldens`), PNGs are not
// committed (sprint rule). The matrix reuses the widget-test pump helper.
import 'money_tab_test.dart' as base;

void main() {
  for (final v in goldenVariants) {
    testWidgets('money tab golden ${v.name}', (tester) async {
      await base.pumpForGolden(tester, v);
      await expectLater(
        find.byType(MaterialApp),
        matchesGoldenFile('../../goldens/money_tab_${v.name}.png'),
      );
    });
  }
}
